if (pR === min) sides.push({ axis: 'x', sign: 1 });
if (pT === min) sides.push({ axis: 'y', sign: -1 });
if (pB === min) sides.push({ axis: 'y', sign: 1 });
// if sides span both axes → corner → flip both
