// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves ball-vs-brick collisions for one pass: destroys the brick(s) hit,
// bounces the ball off the touched face and pushes it back out of the
// rectangle. Pure logic, no DOM — called by frame() (see debt #2).
//
// The ball is treated as a point moving along the segment prevBall -> ball
// (the dilated brick, grown by the ball radius, is the swept collider). This
// makes the pass independent of dt: a step longer than the brick can no longer
// tunnel through it.
//
// Returns the list of destroyed bricks so the caller can score them.
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  const prev = state.prevBall ?? ball;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;
  const destroyed = [];

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;

    // Overlap at the sampled position: resolve on the axis of smallest
    // penetration; equal penetration on both axes means a corner hit and both
    // velocities flip.
    const minX = brick.x - ball.r;
    const maxX = brick.x + brick.w + ball.r;
    const minY = brick.y - ball.r;
    const maxY = brick.y + brick.h + ball.r;
    const penL = ball.x - minX;
    const penR = maxX - ball.x;
    const penT = ball.y - minY;
    const penB = maxY - ball.y;
    const min = Math.min(penL, penR, penT, penB);

    const flipX = min === penL || min === penR;
    const flipY = min === penT || min === penB;
    // Corner: both penetrations equal -> flip both axes (not just one).
    if (flipX && flipY) {
      ball.vx = ball.vx < 0 ? Math.abs(ball.vx) : -Math.abs(ball.vx);
      ball.vy = ball.vy < 0 ? Math.abs(ball.vy) : -Math.abs(ball.vy);
      ball.x = penL <= penR ? minX : maxX;
      ball.y = penT <= penB ? minY : maxY;
    } else if (flipX) {
      ball.vx = penL <= penR ? Math.abs(ball.vx) : -Math.abs(ball.vx);
      ball.x = penL <= penR ? minX : maxX;
    } else {
      ball.vy = penT <= penB ? Math.abs(ball.vy) : -Math.abs(ball.vy);
      ball.y = penT <= penB ? minY : maxY;
    }

    brick.alive = false;
    destroyed.push(brick);
  }

  return destroyed;
}

