// Resolves ball-vs-brick collisions for one pass: destroys the brick(s) hit,
// bounces the ball off the touched face and pushes it back out of the
// rectangle. Pure logic, no DOM — called by frame() (see debt #2).
//
// The ball is treated as a point moving along the segment prevBall -> ball
// (the dilated brick, grown by the ball radius, is the swept collider). This
// makes the pass independent of dt: a step longer than the brick can no longer
// tunnel through it. Exactly one collision is resolved per pass (the one at
// the earliest entry time), so a ball pinched in a grid seam (gap 8px < ball
// diameter 14px) bounces once instead of flipping the same axis twice.
//
// Returns the list of destroyed bricks so the caller can score them.
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  const prev = state.prevBall ?? ball;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  // Earliest collision along the swept path (or the overlap at t = 0).
  let best = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(prev.x, prev.y, dx, dy, ball.r, brick);
    if (hit && (!best || hit.t < best.t)) best = { brick, ...hit };
  }
  if (!best) return [];

  const { brick, t, nx, ny } = best;

  // Place the ball at the moment of contact (for a swept entry, t > 0).
  if (t > 0) {
    ball.x = prev.x + dx * t;
    ball.y = prev.y + dy * t;
  }

  // Bounce on the touched face(s); a corner (both axes) flips both velocities.
  if (nx !== 0) {
    ball.vx = -ball.vx;
    ball.x = nx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (ny !== 0) {
    ball.vy = -ball.vy;
    ball.y = ny < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }

  brick.alive = false;
  return [brick];
}

// Swept circle-vs-brick test: the ball (a point) travels from (px, py) by
// (dx, dy); the brick is dilated by the ball radius. Returns { t, nx, ny } —
// the entry time (0 = overlap at a sampled position) and the touched face
// normal(s) — or null. For an overlap, the axis of smallest penetration is
// chosen; equal penetration on both axes is a corner and both normals are set.
function sweptHit(px, py, dx, dy, r, brick) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  const overlapHit = (cx, cy) => {
    const penL = cx - minX;
    const penR = maxX - cx;
    const penT = cy - minY;
    const penB = maxY - cy;
    const min = Math.min(penL, penR, penT, penB);
    const hitX = min === penL || min === penR;
    const hitY = min === penT || min === penB;
    return {
      t: 0,
      nx: hitX ? (penL <= penR ? -1 : 1) : 0,
      ny: hitY ? (penT <= penB ? -1 : 1) : 0,
    };
  };

  const ex = px + dx;
  const ey = py + dy;
  const inside = (cx, cy) => cx >= minX && cx <= maxX && cy >= minY && cy <= maxY;

  if (inside(px, py)) return overlapHit(px, py); // was already overlapping
  if (inside(ex, ey)) return overlapHit(ex, ey); // ended inside

  // Slab test: first entry of the segment into the dilated rectangle.
  const tInX = dx !== 0 ? (dx > 0 ? (minX - px) / dx : (maxX - px) / dx) : null;
  const tInY = dy !== 0 ? (dy > 0 ? (minY - py) / dy : (maxY - py) / dy) : null;
  const tOutX = dx !== 0 ? (dx > 0 ? (maxX - px) / dx : (minX - px) / dx) : Infinity;
  const tOutY = dy !== 0 ? (dy > 0 ? (maxY - py) / dy : (minY - py) / dy) : Infinity;
  if (dx === 0 && (px < minX || px > maxX)) return null;
  if (dy === 0 && (py < minY || py > maxY)) return null;

  const entries = [];
  if (tInX !== null) entries.push({ t: tInX, nx: dx > 0 ? -1 : 1 });
  if (tInY !== null) entries.push({ t: tInY, ny: dy > 0 ? -1 : 1 });
  if (entries.length === 0) return null;

  const tIn = Math.max(...entries.map((e) => e.t));
  const tOut = Math.min(tOutX, tOutY, 1);
  if (tIn < 0 || tIn > tOut || tIn > 1) return null;

  const atEntry = entries.filter((e) => e.t === tIn);
  const hit = { t: tIn, nx: 0, ny: 0 };
  for (const e of atEntry) {
    if (e.nx !== undefined) hit.nx = e.nx;
    if (e.ny !== undefined) hit.ny = e.ny;
  }
  return hit;
}

