export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember the position before the move: brick collision resolution sweeps
  // the segment prevBall -> ball, which is what makes it dt-independent.
  state.prevBall = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle. Two failures fixed here: the old point test on `ball.x` missed
  // the paddle corners, and the final-position test let a fast ball tunnel
  // through the paddle (level 4 at dt 0.05: step 26.5px > 26px = PADDLE_H +
  // 2*BALL_R). The check now sweeps the segment and uses a circle-vs-rect
  // overlap; the ball always exits through the top of the paddle. The rebound
  // angle keeps a minimum horizontal component (no dead angle at the center)
  // and the velocity is renormalised to the level speed.
  if (ball.vy > 0) {
    const prevX = state.prevBall.x;
    const prevY = state.prevBall.y;
    const crossedTop =
      (prevY + ball.r <= paddle.y && ball.y + ball.r >= paddle.y) ||
      (prevY + ball.r >= paddle.y && prevY + ball.r <= paddle.y + paddle.h);
    const minX = Math.min(prevX, ball.x) - ball.r;
    const maxX = Math.max(prevX, ball.x) + ball.r;
    if (crossedTop && maxX >= paddle.x && minX <= paddle.x + paddle.w) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      const clamped = Math.max(Math.abs(hit), 0.25) * Math.sign(hit || 1);
